foreach($days as$date=>$day){$punches=$day['punches'];$hasRecords=count($punches)>0;$weekend=(int)(new DateTimeImmutable($date))->format('N')>=6;$classes='tm-cell'.(($weekend||$day['holiday'])?' off':'').($day['holiday']?' holiday':'');$absence=$day['absences'][0]??null;$justified=$absence&&$absence['kind']==='justified';echo"<a href='#' class='{$classes}' data-tm-date='{$date}'><div class='d-flex justify-content-between align-items-start'><strong>".(int)substr($date,8,2)."</strong><span class='d-flex align-items-center gap-2'>";if($hasRecords)echo"<span class='tm-status ".($day['incomplete']?'incomplete':'complete')."' title='".($day['incomplete']?'Incompleto':'Completo')."'></span>";if($absence)echo"<i class='ti ti-user-exclamation tm-absence ".($justified?'justified':'')."' title='Falta ".($justified?'justificada':'não justificada')."'></i>";echo"</span></div>";if($day['holiday'])echo"<div class='badge bg-red-lt mt-2'>".tmEsc((string)$day['holiday']['name'])."</div>";if($absence)echo"<div class='tm-absence-label ".($justified?'tm-green':'tm-red')."'>Falta ".($justified?'justificada':'não justificada')."</div>";if($hasRecords){$first=substr((string)$punches[0]['punch_at'],11,5);$last=substr((string)$punches[count($punches)-1]['punch_at'],11,5);echo"<div class='tm-cell-time'>{$first} → {$last}</div><div class='tm-cell-worked'>".tmDuration((int)$day['worked'])."</div><div class='tm-cell-balance ".($day['balance']<0?'tm-red':'tm-green')."'>".tmBalance((int)$day['balance'])."</div>";}echo"</a>";}
