$csrf=Session::getNewCSRFToken();echo"<div class='modal fade' id='tmDay' tabindex='-1'><div class='modal-dialog modal-xl modal-dialog-scrollable'><div class='modal-content'><form method='post' enctype='multipart/form-data' action='/plugins/demandas/front/punch.form.php'><div class='modal-header'><h3 class='modal-title' id='tm-title'>Editar registros</h3><button class='btn-close' type='button' data-bs-dismiss='modal'></button></div><div class='modal-body'><input type='hidden' name='_glpi_csrf_token' value='{$csrf}'><input type='hidden' name='users_id' value='{$target}'><input type='hidden' name='punch_date' id='tm-date'><div id='tm-records' class='d-grid gap-3'></div><button class='btn btn-outline-primary w-100 my-3' type='button' id='tm-add'><i class='ti ti-plus me-1'></i>Adicionar marcação</button><div class='tm-absence-box'><div class='d-flex flex-wrap justify-content-between gap-3 align-items-center'><div><h4 class='mb-1'><i class='ti ti-user-x text-danger me-2'></i>Ausência</h4><div class='text-muted'>Registre falta integral ou parcial e informe se existe justificativa.</div></div><button class='btn btn-outline-danger' type='button' id='tm-absence-toggle'>Registrar ausência</button></div><input type='hidden' name='absence_action' id='tm-absence-action' value='keep'><div id='tm-absence-fields' class='mt-4 d-none'><label class='form-label'>Justificativa</label><div class='d-flex gap-4 mb-3'><label class='form-check'><input class='form-check-input' type='radio' name='absence_kind' value='unjustified' checked><span class='form-check-label'>Não justificada</span></label><label class='form-check'><input class='form-check-input' type='radio' name='absence_kind' value='justified'><span class='form-check-label'>Justificada</span></label></div><label class='form-label'>Período da falta</label><div class='d-flex gap-4 mb-3'><label class='form-check'><input class='form-check-input' type='radio' name='absence_scope' value='whole' checked><span class='form-check-label'>Dia in