$script=<<<'JS'
<script>
const tmDays=__TM_DAYS__;
const modal=new bootstrap.Modal(document.getElementById('tmDay'));
const records=document.getElementById('tm-records');
const typeOptions=[['entrada_manha','Entrada Manhã'],['saida_manha','Saída Manhã'],['entrada_tarde','Entrada Tarde'],['saida_tarde','Saída Tarde'],['entrada_intermediaria','Entrada intermediária'],['saida_intermediaria','Saída intermediária']];
let rowIndex=0;
function esc(v){const d=document.createElement('div');d.textContent=v||'';return d.innerHTML}
function addRow(p={}){const i=rowIndex++;const div=document.createElement('div');div.className='tm-record';div.innerHTML=`<input type="hidden" name="records[${i}][id]" value="${Number(p.id||0)}"><div><label class="form-label">Horário</label><input class="form-control" type="time" name="records[${i}][time]" value="${esc(p.time)}"></div><div><label class="form-label">Tipo</label><select class="form-select" name="records[${i}][type]">${typeOptions.map(o=>`<option value="${o[0]}" ${p.type===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></div><div><label class="form-label">NSR</label><input class="form-control" name="records[${i}][nsr]" maxlength="50" value="${esc(p.nsr)}"></div><div class="tm-note"><label class="form-label">Observação</label><input class="form-control" name="records[${i}][note]" maxlength="500" value="${esc(p.note)}"></div><button type="button" class="btn btn-icon btn-ghost-danger tm-remove" title="Excluir"><i class="ti ti-trash"></i></button>`;div.querySelector('.tm-remove').onclick=()=>div.remove();records.appendChild(div)}
function refreshAbsenceFields(){const partial=document.querySelector('[name="absence_scope"]:checked')?.value==='partial';const justified=document.querySelector('[name="absence_kind"]:checked')?.value==='justified';document.getElementById('tm-absence-period').classList.toggle('d-none',!partial);document.getElementById('tm-full-day-info').classList.toggle('d-none',partial);document.getElementById('tm-absence-attachments').classList.toggle('d-none',!justified)}
function openDay(date){const data=tmDays[date]||{punches:[],absences:[]};rowIndex=0;records.innerHTML='';data.punches.forEach(addRow);if(!data.punches.length)addRow();document.getElementById('tm-date').value=date;const parts=date.split('-');document.getElementById('tm-title').textContent=`Editar registros de ${parts[2]}/${parts[1]}/${parts[0]}`;const absence=data.absences[0];const action=document.getElementById('tm-absence-action'),fields=document.getElementById('tm-absence-fields'),button=document.getElementById('tm-absence-toggle');action.value='keep';fields.classList.add('d-none');button.textContent=absence?'Editar ausência':'Registrar ausência';document.querySelector(`[name="absence_kind"][value="${absence?.kind||'unjustified'}"]`).checked=true;document.querySelector(`[name="absence_scope"][value="${absence&&!absence.full?'partial':'whole'}"]`).checked=true;document.querySelector('[name="absence_start"]').value=absence?.start||'';document.querySelector('[name="absence_end"]').value=absence?.end||'';document.querySelector('[name="absence_reason"]').value=absence?.reason||'';document.querySelector('[name="absence_files[]"]').value='';document.getElementById('tm-existing-files').innerHTML=absence?.files?.length?`Anexos já enviados: ${absence.files.map(esc).join(', ')}`:'';refreshAbsenceFields();modal.show()}
document.querySelectorAll('[data-tm-date]').forEach(el=>el.onclick=e=>{e.preventDefault();openDay(el.dataset.tmDate)});
document.getElementById('tm-new').onclick=e=>openDay(e.currentTarget.dataset.date);
document.getElementById('tm-add').onclick=()=>addRow();
document.getElementById('tm-absence-toggle').onclick=()=>{document.getElementById('tm-absence-fields').classList.remove('d-none');document.getElementById('tm-absence-action').value='set';refreshAbsenceFields()};
document.getElementById('tm-absence-remove').onclick=()=>{document.getElementById('tm-absence-fields').classList.add('d-none');document.getElementById('tm-absence-action').value='remove';document.getElementById('tm-absence-toggle').textContent='Registrar ausência'};
document.querySelectorAll('[name="absence_scope"],[name="absence_kind"]').forEach(el=>el.addEventListener('change',()=>{document.getElementById('tm-absence-action').value='set';refreshAbsenceFields()}));
</script></div>
JS;
